    config = Config()
    config.config["mundo"] = {"regioes": texto}
    return _materializar(config.get_config_section_key_dict_dict_dict("mundo", "regioes"))

def map_split(value, splitter):
    return map(lambda x: x.split(splitter), value.split(splitter))

